using System.Numerics;
using CS2Review.Core;
if(args.Length==5&&args[0]=="--import"){
 var service=new MapResourceService(args[4]);var watch=System.Diagnostics.Stopwatch.StartNew();var resource=await service.ImportFromGameAsync(args[1],args[2],args[3],CancellationToken.None);Console.WriteLine(System.Text.Json.JsonSerializer.Serialize(resource));Console.WriteLine("seconds="+watch.Elapsed.TotalSeconds);return 0;
}
if(args.Length==5&&args[0]=="--cancel"){
 using var cancel=new CancellationTokenSource(TimeSpan.FromMilliseconds(100));try{await new MapResourceService(args[4]).ImportFromGameAsync(args[1],args[2],args[3],cancel.Token);throw new Exception("expected cancellation");}catch(OperationCanceledException){if(File.Exists(Path.Combine(args[3],args[1],"manifest.json"))||(Directory.Exists(Path.Combine(args[3],args[1]))&&Directory.EnumerateDirectories(Path.Combine(args[3],args[1]),"staging-*").Any()))throw new Exception("cancelled import retained staged output");Console.WriteLine("PASS real cancellation: worker stopped, no manifest or staging");}return 0;
}
if(args.Length==3&&args[0]=="--failure"){
 var root=Path.GetFullPath(args[2]);var game=Path.Combine(root,"fixture","game","csgo");Directory.CreateDirectory(Path.Combine(game,"maps"));File.WriteAllText(Path.Combine(game,"steam.inf"),"appID=730");File.WriteAllBytes(Path.Combine(game,"pak01_dir.vpk"),[1,2,3]);File.WriteAllBytes(Path.Combine(game,"maps","de_mirage.vpk"),[1,2,3]);var output=Path.Combine(root,"cache");try{await new MapResourceService(args[1]).ImportFromGameAsync("de_mirage",Path.Combine(root,"fixture"),output,CancellationToken.None);throw new Exception("expected exporter failure");}catch(IOException){if(File.Exists(Path.Combine(output,"de_mirage","manifest.json"))||Directory.EnumerateDirectories(Path.Combine(output,"de_mirage"),"staging-*").Any())throw new Exception("failed import retained staging");Console.WriteLine("PASS actual CLI failure: no manifest or staging");}return 0;
}
var failures=new List<string>();
var total=0;
void Test(string name,Action test){total++;try{test();Console.WriteLine("PASS "+name);}catch(Exception e){failures.Add(name);Console.WriteLine("FAIL "+name+": "+e.Message);}}
void Check(bool ok){if(!ok)throw new Exception("assertion failed");}
void Throws<T>(Action action) where T:Exception {try{action();}catch(T){return;}throw new Exception("expected "+typeof(T).Name);}
var wall=new[]{new SpatialTriangle(new(0,-1,-1),new(0,1,-1),new(0,1,1)),new SpatialTriangle(new(0,-1,-1),new(0,1,1),new(0,-1,1))};
Test("two sided wall blocks segments while open and parallel paths clear",()=>{var mesh=new SpatialMesh(wall);Check(mesh.TraceStaticSegment(new(-1,0,0),new(1,0,0)));Check(mesh.TraceStaticSegment(new(1,0,0),new(-1,0,0)));Check(!mesh.TraceStaticSegment(new(-1,2,0),new(1,2,0)));Check(!mesh.TraceStaticSegment(new(-1,0,0),new(-1,1,0)));});
Test("invalid and zero length rays cannot report clear",()=>{var mesh=new SpatialMesh(wall);Throws<ArgumentException>(()=>mesh.TraceStaticSegment(Vector3.Zero,Vector3.Zero));Throws<ArgumentException>(()=>mesh.TraceStaticSegment(new(float.NaN,0,0),Vector3.One));});
Test("BVH matches independent brute force over deterministic random rays",()=>{var random=new Random(42);var tris=Enumerable.Range(0,100).Select(_=>new SpatialTriangle(new(random.NextSingle()*5,random.NextSingle()*5,random.NextSingle()*5),new(random.NextSingle()*5,random.NextSingle()*5,random.NextSingle()*5),new(random.NextSingle()*5,random.NextSingle()*5,random.NextSingle()*5))).ToArray();var mesh=new SpatialMesh(tris);for(var i=0;i<200;i++){var a=new Vector3(random.NextSingle()*8,random.NextSingle()*8,random.NextSingle()*8);var b=new Vector3(random.NextSingle()*8,random.NextSingle()*8,random.NextSingle()*8);Check(mesh.TraceStaticSegment(a,b)==tris.Any(t=>Reference(t,a,b)));}});
Test("yaw pitch field of view handles front back and elevated points",()=>{Check(SpatialMath.IsWithinFov(Vector3.Zero,new(2,0,0),0,0,90));Check(!SpatialMath.IsWithinFov(Vector3.Zero,new(-2,0,0),0,0,90));Check(SpatialMath.IsWithinFov(Vector3.Zero,new(0,0,2),0,-90,90));Throws<ArgumentException>(()=>SpatialMath.IsWithinFov(Vector3.Zero,Vector3.Zero,0,0,90));});
Test("overview maps upper left and preserves world y inversion",()=>{var o=new MapOverview{PosX=-3230,PosY=1713,Scale=5,ImageSize=1024};Check(o.Project(-3230,1713)==Vector2.Zero);Check(o.Project(-3220,1703)==new Vector2(2,2));});
Test("AWMH preserves genuine origin and rejects corrupt indices",()=>{using var data=new MemoryStream();using(var w=new BinaryWriter(data,System.Text.Encoding.UTF8,true)){w.Write("AWMH"u8);w.Write(1);w.Write(3);w.Write(1);foreach(var p in new[]{Vector3.Zero,Vector3.UnitX,Vector3.UnitY}){w.Write(p.X);w.Write(p.Y);w.Write(p.Z);}w.Write(0);w.Write(1);w.Write(2);}data.Position=0;var mesh=SpatialMesh.ReadAwmh(data);Check(mesh.TriangleCount==1);data.Position=data.Length-4;new BinaryWriter(data).Write(3);data.Position=0;Throws<InvalidDataException>(()=>SpatialMesh.ReadAwmh(data));});
Test("pre cancelled import makes no output and rejects traversal names",()=>{var root=Path.Combine(Path.GetTempPath(),"map-test-"+Guid.NewGuid());var service=new MapResourceService("absent.exe");Throws<ArgumentException>(()=>service.ImportFromGameAsync("../de_mirage","missing",root,CancellationToken.None).GetAwaiter().GetResult());Throws<OperationCanceledException>(()=>service.ImportFromGameAsync("de_mirage","missing",root,new CancellationToken(true)).GetAwaiter().GetResult());Check(!Directory.Exists(root));});
Test("Source2 physics GLB raw Hammer coordinates survive display matrix",()=>{var root=Path.Combine(Path.GetTempPath(),"map-glb-"+Guid.NewGuid());Directory.CreateDirectory(root);try{var input=Path.Combine(root,"physics.glb");Fixture(input,false);var output=Path.Combine(root,"mesh.bin");var counts=SpatialSource2Glb.ConvertToAwmh(input,output,CancellationToken.None);Check(counts==(3,1));using var f=File.OpenRead(output);Check(SpatialMesh.ReadAwmh(f).TraceStaticSegment(new(.2f,.2f,-1),new(.2f,.2f,1)));Fixture(input,true);Throws<InvalidDataException>(()=>SpatialSource2Glb.ConvertToAwmh(input,output,CancellationToken.None));}finally{Directory.Delete(root,true);}});
Test("missing resource cache and traversal requests are safely unavailable",()=>{var service=new MapResourceService("absent.exe");Check(service.Find("de_mirage",Path.Combine(Path.GetTempPath(),"absent-"+Guid.NewGuid())) is null);Throws<ArgumentException>(()=>service.Find("../../private",Path.GetTempPath()));});
Test("cache manifest escaping asset root is rejected",()=>{var root=Path.Combine(Path.GetTempPath(),"map-unsafe-"+Guid.NewGuid());Directory.CreateDirectory(Path.Combine(root,"de_mirage"));try{File.WriteAllText(Path.Combine(root,"de_mirage","manifest.json"),"{\"mapName\":\"de_mirage\",\"resourceDirectory\":\"../../private\"}");Check(new MapResourceService("absent.exe").Find("de_mirage",root) is null);}finally{Directory.Delete(root,true);}});
Test("Steam library locator follows explicit libraries and manifest install name",()=>{var root=Path.Combine(Path.GetTempPath(),"steam-fixture-"+Guid.NewGuid());var library=Path.Combine(root,"extra-library");var install=Path.Combine(library,"steamapps","common","Test CS2");Directory.CreateDirectory(Path.Combine(root,"steamapps"));Directory.CreateDirectory(Path.Combine(install,"game","csgo"));try{File.WriteAllText(Path.Combine(install,"game","csgo","steam.inf"),"appID=730");File.WriteAllText(Path.Combine(library,"steamapps","appmanifest_730.acf"),"\"AppState\" { \"installdir\" \"Test CS2\" }");File.WriteAllText(Path.Combine(root,"steamapps","libraryfolders.vdf"),"\"libraryfolders\" { \"0\" { \"path\" \""+library.Replace("\\","\\\\")+"\" } }");Check(MapInstallLocator.FindInstalls([root]).Contains(install));}finally{Directory.Delete(root,true);}});
Test("explicit resource provenance binds exact source and geometry without becoming verified",()=>{var r=new MapResource{MapName="de_mirage",GeometrySha256=new string('a',64),ResourceDirectory="assets-"+new string('a',24)};var p=MapResourceProvenance.UserAsserted(r,new string('b',64));Check(p.Status=="user-asserted"&&!p.AllowsVerifiedVisibility);Check(p.IsBoundTo(r,new string('b',64)));Check(!p.IsBoundTo(r,new string('c',64)));r.GeometrySha256=new string('c',64);Check(!p.IsBoundTo(r,new string('b',64)));Throws<ArgumentException>(()=>MapResourceProvenance.UserAsserted(r,"not-a-hash"));});
var cache=Environment.GetEnvironmentVariable("CS2_MAP_TEST_CACHE");
if(!string.IsNullOrEmpty(cache))Test("cached overview metadata must match its hashed source and damaged nullable fields degrade",()=>
{
 var service=new MapResourceService("unused.exe");var original=service.Find("de_mirage",cache)??throw new Exception("cache missing");
 var root=Path.Combine(Path.GetTempPath(),"map-overview-"+Guid.NewGuid());var mapRoot=Path.Combine(root,"de_mirage");var assets=Path.Combine(mapRoot,original.ResourceDirectory);Directory.CreateDirectory(assets);
 try
 {
  foreach(var file in new[]{"radar.png","geometry.mesh","overview.txt","world_physics.vmdl_c","source_texture.vtex_c","physics.bin"})File.Copy(Path.Combine(Path.GetDirectoryName(original.ImagePath)!,file),Path.Combine(assets,file));
  var manifestText=File.ReadAllText(original.ManifestPath);
  foreach(var property in new[]{"posX","posY","scale","imageSize","rotate","overview-null","hash-null"})
  {
   var node=System.Text.Json.Nodes.JsonNode.Parse(manifestText)!;
   if(property=="overview-null")node["overview"]=null;
   else if(property=="hash-null")node["imageSha256"]=null;
   else if(property=="imageSize"||property=="rotate")node["overview"]![property]=node["overview"]![property]!.GetValue<int>()+1;
   else node["overview"]![property]=node["overview"]![property]!.GetValue<double>()+1;
   File.WriteAllText(Path.Combine(mapRoot,"manifest.json"),node.ToJsonString());
   if(service.Find("de_mirage",root) is not null)throw new Exception("accepted damaged "+property);
  }
 }
 finally{Directory.Delete(root,true);}
});
if(!string.IsNullOrEmpty(cache))foreach(var map in new[]{"de_mirage","de_dust2"})Test("real "+map+" cache geometry and projection",()=>{var r=new MapResourceService("unused.exe").Find(map,cache)??throw new Exception("cache missing");Check(r.MatchStatus=="unknown"&&r.Overview.ImageSize==1024&&r.TriangleCount>100_000);using var f=File.OpenRead(r.GeometryPath);var mesh=SpatialMesh.ReadAwmh(f);Check(mesh.TriangleCount==r.TriangleCount);Check(r.Overview.Project(r.Overview.PosX,r.Overview.PosY)==Vector2.Zero);Check(mesh.TraceStaticSegment(new(0,0,-2000),new(0,0,2000)));Console.WriteLine($"real {map}: {mesh.TriangleCount} triangles; vertical ray intersects recorded collision; unknown demo version");});
if(!string.IsNullOrEmpty(cache))Test("tampered real cache hash and geometry metadata reject import identity",()=>{var service=new MapResourceService("unused.exe");var r=service.Find("de_mirage",cache)??throw new Exception("cache missing");var root=Path.Combine(Path.GetTempPath(),"map-cache-"+Guid.NewGuid());var mapRoot=Path.Combine(root,"de_mirage");var assets=Path.Combine(mapRoot,r.ResourceDirectory);Directory.CreateDirectory(assets);try{foreach(var file in new[]{"radar.png","geometry.mesh","overview.txt","world_physics.vmdl_c","source_texture.vtex_c","physics.bin"})File.Copy(Path.Combine(Path.GetDirectoryName(r.ImagePath)!,file),Path.Combine(assets,file));File.Copy(r.ManifestPath,Path.Combine(mapRoot,"manifest.json"));Check(service.Find("de_mirage",root) is not null);using(var f=File.OpenWrite(Path.Combine(assets,"radar.png"))){f.Position=30;f.WriteByte(255);}Check(service.Find("de_mirage",root) is null);File.Copy(r.ImagePath,Path.Combine(assets,"radar.png"),true);var manifest=System.Text.Json.Nodes.JsonNode.Parse(File.ReadAllText(r.ManifestPath))!;manifest["triangleCount"]=-1;File.WriteAllText(Path.Combine(mapRoot,"manifest.json"),manifest.ToJsonString());Check(service.Find("de_mirage",root) is null);}finally{Directory.Delete(root,true);}});
static void Fixture(string path,bool corrupt){var json="{\"asset\":{\"version\":\"2.0\"},\"buffers\":[{\"byteLength\":48}],\"bufferViews\":[{\"buffer\":0,\"byteOffset\":0,\"byteLength\":36},{\"buffer\":0,\"byteOffset\":36,\"byteLength\":12}],\"accessors\":[{\"bufferView\":0,\"componentType\":5126,\"count\":3,\"type\":\"VEC3\"},{\"bufferView\":1,\"componentType\":5125,\"count\":3,\"type\":\"SCALAR\"}],\"meshes\":[{\"primitives\":[{\"attributes\":{\"POSITION\":0},\"indices\":1}]}],\"nodes\":[{\"mesh\":0,\"matrix\":[0,0,0.0254,0,0.0254,0,0,0,0,0.0254,0,0,0,0,0,1]}]}";while(json.Length%4!=0)json+=" ";var jb=System.Text.Encoding.UTF8.GetBytes(json);using var w=new BinaryWriter(File.Create(path));w.Write("glTF"u8);w.Write(2);w.Write(12+8+jb.Length+8+48);w.Write(jb.Length);w.Write("JSON"u8);w.Write(jb);w.Write(48);w.Write(new byte[]{66,73,78,0});foreach(var v in new[]{Vector3.Zero,Vector3.UnitX,Vector3.UnitY}){w.Write(v.X);w.Write(v.Y);w.Write(v.Z);}w.Write(0);w.Write(1);w.Write(corrupt?3:2);}
static bool Reference(SpatialTriangle t,Vector3 a,Vector3 b){var n=Vector3.Cross(t.B-t.A,t.C-t.A);var d=b-a;var den=Vector3.Dot(n,d);if(Math.Abs(den)<1e-6)return false;var q=Vector3.Dot(n,t.A-a)/den;if(q<0||q>1)return false;var p=a+d*q;var c1=Vector3.Dot(n,Vector3.Cross(t.B-t.A,p-t.A));var c2=Vector3.Dot(n,Vector3.Cross(t.C-t.B,p-t.B));var c3=Vector3.Dot(n,Vector3.Cross(t.A-t.C,p-t.C));return c1>=-1e-6&&c2>=-1e-6&&c3>=-1e-6;}
Console.WriteLine($"{total-failures.Count}/{total} passed");return failures.Count==0?0:1;
